import{_ as e,o as s,c as i,ag as n}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Repair Station Business","description":"","frontmatter":{},"headers":[],"relativePath":"es/repair-station-business/index.md","filePath":"es/repair-station-business/index.md"}'),o={name:"es/repair-station-business/index.md"};function t(r,a,c,l,p,d){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="repair-station-business" tabindex="-1">Repair Station Business <a class="header-anchor" href="#repair-station-business" aria-label="Permalink to &quot;Repair Station Business&quot;">​</a></h1><p>El complemento de pago de la <a href="/es/repair-station/">Repair Station</a>: los jugadores compran estaciones de reparación, las abastecen de piezas, fijan sus precios y cobran la caja. Todo se gestiona desde una tablet en la estación, y cada ajuste se edita en el juego.</p><h2 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to &quot;Características&quot;">​</a></h2><ul><li><strong>Estaciones en venta</strong>: eliges qué Repair Stations se pueden comprar y a qué precio. Consulta <a href="/es/repair-station-business/ownership">Propiedad</a>.</li><li><strong>Tablet del propietario</strong>: stock, caja, últimas operaciones, precios, nombre y venta de la estación, en un solo sitio.</li><li><strong>Piezas</strong>: cada reparación gasta piezas del stock de la estación, compradas con la cuenta bancaria o entregadas como objetos. Consulta <a href="/es/repair-station-business/stock">Stock</a>.</li><li><strong>Precios del propietario</strong>: cada propietario fija un porcentaje del precio base, dentro de los límites que elijas, y se retiene un impuesto de cada pago.</li><li><strong>Finales justos</strong>: un propietario que vende, es expulsado o se vuelve inactivo recibe parte del precio de compra más la caja, incluso sin conexión.</li><li><strong>Panel de administración</strong>: pon estaciones en venta, cambia su precio, ajusta el stock de las estaciones con propietario o expulsa a un propietario sin salir del juego.</li><li><strong>API HTTP y webhooks</strong>: estaciones, registro y estadísticas para tu web, y un mensaje de Discord por cada compra, reposición, retirada y pérdida de estación. Consulta <a href="/es/repair-station-business/api">API y webhooks</a>.</li><li><strong>Seis idiomas</strong>: inglés, francés, español, portugués, polaco, alemán.</li></ul><h2 id="compatibilidad" tabindex="-1">Compatibilidad <a class="header-anchor" href="#compatibilidad" aria-label="Permalink to &quot;Compatibilidad&quot;">​</a></h2><ul><li>Frameworks: ESX Legacy, QBCore, QBox, ox_core, detectados automáticamente.</li><li>Dependencias: oxmysql, <code>nay_lib</code> y la <a href="/es/repair-station/">Repair Station</a> (<code>nay_repair</code>), incluidos con tu compra de los scripts.</li></ul><h2 id="instalacion" tabindex="-1">Instalación <a class="header-anchor" href="#instalacion" aria-label="Permalink to &quot;Instalación&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span>
<span class="line"><span>ensure nay_repair_business</span></span></code></pre></div><p>Los pasos completos están en la página <a href="/es/getting-started">Primeros pasos</a>. Después date <code>nay_repair_business.config</code> (o <code>nay.admin</code>) y abre <code>/nay</code>, o escribe <code>/nay:repairbusiness</code> para el panel de administración. Marca en el panel las estaciones que quieras vender: hasta entonces, las estaciones funcionan como simples Repair Stations.</p>`,9)])])}const b=e(o,[["render",t]]);export{m as __pageData,b as default};
